def has_repeat_slow(items):
    for i in range(len(items)):
        for j in range(i + 1, len(items)):
            if items[i] == items[j]:
                return True
    return False

def has_repeat_fast(items):
    return len(set(items)) < len(items)

def keep_ends(text, budget):
    if len(text) <= budget:
        return text
    head = (budget * 2) // 3
    tail = budget - head
    return f'{text[:head]} ... {text[-tail:]} ({len(text)} chars, middle omitted)'

def describe(value, depth=0):
    if depth > 6:
        return '...'
    if isinstance(value, dict):
        lines = []
        for k, v in value.items():
            lines.append(f'{k}: {describe(v, depth + 1)}')
        return '\n'.join(lines)
    return str(value)

